import{_ as s,c as i,o as e,ag as t}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Post-installation","description":"","frontmatter":{},"headers":[],"relativePath":"post-installation/index.md","filePath":"post-installation/index.md","lastUpdated":1792149212000}'),n={name:"post-installation/index.md"};function l(p,a,o,h,d,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="post-installation" tabindex="-1">Post-installation <a class="header-anchor" href="#post-installation" aria-label="Permalink to &quot;Post-installation&quot;">​</a></h1><p>Run these commands after reboot as your regular user. Commands needing administrative privileges use <code>sudo</code>.</p><h2 id="network-and-keyboard" tabindex="-1">Network and keyboard <a class="header-anchor" href="#network-and-keyboard" aria-label="Permalink to &quot;Network and keyboard&quot;">​</a></h2><p>Connect Wi-Fi through your desktop&#39;s network settings or <code>nmtui</code>. The installed system uses NetworkManager; the ISO&#39;s <code>iwctl</code> setup is separate.</p><p>Set your keyboard layout in the desktop settings. For X11 sessions and display managers that use the system X11 layout, this example sets German:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-x11-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de</span></span></code></pre></div><p>This does not replace <code>/etc/vconsole.conf</code>, which controls the console and the encrypted-root unlock prompt. If you change that file on an encrypted system, regenerate the initramfs with <code>sudo mkinitcpio -P</code>.</p><h2 id="aur-packages" tabindex="-1">AUR packages <a class="header-anchor" href="#aur-packages" aria-label="Permalink to &quot;AUR packages&quot;">​</a></h2><p>Use <code>sudo pacman -S package</code> for official repository packages. The <a href="https://wiki.archlinux.org/title/Arch_User_Repository" target="_blank" rel="noreferrer">Arch User Repository</a> contains user-maintained build instructions, not officially supported binary packages. Review the <code>PKGBUILD</code>, install scripts and source URLs before building, including when a helper offers to show changes.</p><p>Install build prerequisites:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --needed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><p>Choose one optional helper. Run <code>makepkg</code> as your regular user, never root. After cloning, read the build files before running the final command:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-m0sCG" id="tab-YQXR3fK" checked><label data-title="paru" for="tab-YQXR3fK">paru</label><input type="radio" name="group-m0sCG" id="tab-3DwFpNB"><label data-title="yay" for="tab-3DwFpNB">yay</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://aur.archlinux.org/paru.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paru</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">less</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PKGBUILD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">makepkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -si</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://aur.archlinux.org/yay.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">less</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PKGBUILD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">makepkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -si</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div></div></div><p>Examples below use <code>paru</code>; substitute <code>yay</code> if that is your helper.</p><table tabindex="0"><thead><tr><th>Task</th><th>Command</th></tr></thead><tbody><tr><td>Upgrade repository and AUR packages</td><td><code>paru -Syu</code></td></tr><tr><td>Install an AUR package</td><td><code>paru -S package</code></td></tr><tr><td>Inspect installed package information</td><td><code>pacman -Qi package</code></td></tr><tr><td>Remove a package and unneeded dependencies</td><td><code>sudo pacman -Rns package</code></td></tr><tr><td>List foreign packages, including AUR packages</td><td><code>pacman -Qm</code></td></tr></tbody></table><p>Review removal lists before confirming. Do not bypass dependency checks to force a package replacement.</p><p>AUR packages may need rebuilding after library upgrades. The official <code>rebuild-detector</code> package helps find affected packages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebuild-detector</span></span></code></pre></div><h2 id="software-centers-and-flatpak" tabindex="-1">Software centers and Flatpak <a class="header-anchor" href="#software-centers-and-flatpak" aria-label="Permalink to &quot;Software centers and Flatpak&quot;">​</a></h2><p>For Plasma:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwupd</span></span></code></pre></div><p>For GNOME:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome-software</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwupd</span></span></code></pre></div><p>Configure remotes using the <a href="https://flathub.org/en/setup/Arch" target="_blank" rel="noreferrer">Flatpak setup instructions</a>. These software centers can manage Flatpaks and supported firmware updates. Repository package support depends on installed backends such as PackageKit; they do not replace AUR review or Arch&#39;s manual upgrade interventions. This guide uses pacman for repository packages.</p><p><a href="https://flathub.org/apps/io.github.kolunmi.Bazaar" target="_blank" rel="noreferrer">Bazaar</a> is another Flatpak-focused option. After configuring Flathub:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flathub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> io.github.kolunmi.Bazaar</span></span></code></pre></div><h2 id="media-codecs" tabindex="-1">Media codecs <a class="header-anchor" href="#media-codecs" aria-label="Permalink to &quot;Media codecs&quot;">​</a></h2><p>For applications using GStreamer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gst-libav</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gst-plugins-base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gst-plugins-good</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gst-plugins-bad</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gst-plugins-ugly</span></span></code></pre></div><p>Install <code>gst-plugin-va</code> if you need GStreamer VA-API acceleration and have a supported video driver. Other players may use their own codec stack; see <a href="https://wiki.archlinux.org/title/GStreamer" target="_blank" rel="noreferrer">GStreamer</a>.</p><h2 id="fonts" tabindex="-1">Fonts <a class="header-anchor" href="#fonts" aria-label="Permalink to &quot;Fonts&quot;">​</a></h2><p>A small general-purpose selection is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noto-fonts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noto-fonts-emoji</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ttf-liberation</span></span></code></pre></div><p>Add <code>noto-fonts-cjk</code> for Chinese, Japanese and Korean coverage. Choose additional fonts for the languages and applications you use instead of installing every font package. See <a href="https://wiki.archlinux.org/title/Fonts" target="_blank" rel="noreferrer">Fonts</a>.</p><h3 id="windows-and-macos-fonts" tabindex="-1">Windows and macOS fonts <a class="header-anchor" href="#windows-and-macos-fonts" aria-label="Permalink to &quot;Windows and macOS fonts&quot;">​</a></h3><p>If you need Microsoft fonts, the AUR&#39;s <code>ttf-ms-win11</code> build instructions describe the required files from a Windows installation or ISO. Review the current <code>PKGBUILD</code> and its licensing requirements, supply the matching sources, and build normally with <code>makepkg -si</code>. Resolve source or checksum mismatches instead of disabling integrity checks.</p><p>Apple&#39;s San Francisco fonts are optional and have their own licensing terms. Check the current AUR build instructions for <code>otf-san-francisco</code> and <code>otf-san-francisco-mono</code> if you need them.</p><h2 id="qt-applications-on-gtk-desktops" tabindex="-1">Qt applications on GTK desktops <a class="header-anchor" href="#qt-applications-on-gtk-desktops" aria-label="Permalink to &quot;Qt applications on GTK desktops&quot;">​</a></h2><p><code>qt6ct</code> can configure Qt 6 applications outside Plasma. Follow <a href="https://wiki.archlinux.org/title/Qt#Configuration" target="_blank" rel="noreferrer">Qt&#39;s configuration guidance</a> for setting <code>QT_QPA_PLATFORMTHEME=qt6ct</code> in your session&#39;s environment. Do not set it globally on Plasma, which supplies its own integration. A Wayland session does not necessarily read <code>~/.profile</code>.</p><h2 id="apfs-access" tabindex="-1">APFS access <a class="header-anchor" href="#apfs-access" aria-label="Permalink to &quot;APFS access&quot;">​</a></h2><p>The official repository contains <code>linux-apfs-rw-dkms</code>. Install the headers for your kernel alongside it, for example <code>linux-headers</code> for <code>linux</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-apfs-rw-dkms</span></span></code></pre></div><p>The <a href="https://github.com/linux-apfs/linux-apfs-rw" target="_blank" rel="noreferrer">upstream driver</a> mounts read-only by default. Write support is experimental and can corrupt data; encrypted APFS volumes are unsupported. Keep valuable data backed up and use read-only access.</p><h2 id="nano-syntax-highlighting" tabindex="-1">Nano syntax highlighting <a class="header-anchor" href="#nano-syntax-highlighting" aria-label="Permalink to &quot;Nano syntax highlighting&quot;">​</a></h2><p>Optional additional syntax definitions are available with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano-syntax-highlighting</span></span></code></pre></div><p>Follow the package&#39;s configuration instructions to enable the definitions you need.</p><h2 id="package-cache-and-regular-updates" tabindex="-1">Package cache and regular updates <a class="header-anchor" href="#package-cache-and-regular-updates" aria-label="Permalink to &quot;Package cache and regular updates&quot;">​</a></h2><p>Use the official cache-cleaning timer, which retains three versions of cached packages by default:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman-contrib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paccache.timer</span></span></code></pre></div><p>Keeping recent packages helps with recovery. Read <a href="/tweaks/">system maintenance and backups</a> before your next upgrade.</p>`,51)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
